const LABEL_HISTORY_KEY="lifeos.checklist.labelHistory.v1.";
function readLabelHistory(projectId=activeProjectId){try{return JSON.parse(localStorage.getItem(LABEL_HISTORY_KEY+projectId)||"{}")}catch{return {}}}
function taskLabelForDate(projectId,taskId,fallback,date){const h=readLabelHistory(projectId)[taskId];if(!h)return fallback;let label=h.baseLabel||fallback;(h.changes||[]).slice().sort((a,b)=>a.date.localeCompare(b.date)).forEach(c=>{if(date>=c.date)label=c.label});return label}
function chooseTaskRename(projectId,taskId,oldLabel,newLabel){const choice=prompt("이름 변경 적용 범위\n1 = 과거 기록까지 모두 변경\n2 = 선택한 날짜부터 변경","2");if(choice===null)return false;if(choice.trim()==="1"){const history=readLabelHistory(projectId);delete history[taskId];localStorage.setItem(LABEL_HISTORY_KEY+projectId,JSON.stringify(history));return true}if(choice.trim()!=="2"){alert("1 또는 2를 입력해 줘.");return false}const effective=prompt("새 이름을 적용할 시작일 (YYYY-MM-DD)",dateNow());if(effective===null)return false;if(!/^\d{4}-\d{2}-\d{2}$/.test(effective)){alert("날짜를 YYYY-MM-DD 형식으로 입력해 줘.");return false}const history=readLabelHistory(projectId);if(!history[taskId])history[taskId]={baseLabel:oldLabel,changes:[]};history[taskId].changes=(history[taskId].changes||[]).filter(c=>c.date!==effective);history[taskId].changes.push({date:effective,label:newLabel});history[taskId].changes.sort((a,b)=>a.date.localeCompare(b.date));localStorage.setItem(LABEL_HISTORY_KEY+projectId,JSON.stringify(history));return true}
