function updateModeButtons(){const min=$("modeMinimum"),full=$("modeFull");if(min){min.classList.toggle("mode-active",minimumMode);min.setAttribute("aria-pressed",String(minimumMode))}if(full){full.classList.toggle("mode-active",!minimumMode);full.setAttribute("aria-pressed",String(!minimumMode))}}
function blank(){let tasks={};groups.forEach(g=>g.tasks.forEach(t=>tasks[t[0]]=false));return {tasks,metrics:{carbs:"",protein:"",fat:"",weight:"",contacts:0,marketing:0,blogs:0,proposals:0,customers:0,revenue:0},forbiddenChecks:{},reflection:{win:"",blocker:"",tomorrow:""}}}
function getRecord(date){return records[date]||blank()}
function syncHealthToChecklist(){let health={};try{health=JSON.parse(localStorage.getItem("lifeos.health.logs.v1")||"{}")}catch{};let changed=false;Object.keys(health).filter(d=>d>="2026-10-01"&&d<="2026-10-11").forEach(d=>{const h=health[d]||{},r=records[d]||blank(),m=h.meals||{},t=h.dailyTotals||{},a=h.activities||{},f=h.foodFlags||{};r.metrics=r.metrics||blank().metrics;r.tasks=r.tasks||blank().tasks;r.forbiddenChecks=r.forbiddenChecks||{};if(h.weight!==""&&h.weight!=null)r.metrics.weight=h.weight;if(t.carbs!=null)r.metrics.carbs=t.carbs;if(t.protein!=null)r.metrics.protein=t.protein;if(t.fat!=null)r.metrics.fat=t.fat;const hasFood=Object.values(m).some(x=>x&&x.food&&x.food!=="기록 없음");if(hasFood)r.tasks.macros=true;const flagKeys=["unprocessed","noFlour","noSweets","noFried"],flagValues=flagKeys.map(k=>f[k]);flagKeys.forEach((k,i)=>{r.forbiddenChecks[k]=flagValues[i]==="x"||flagValues[i]==="ok"||flagValues[i]===true||flagValues[i]==="✓"});if(flagValues.every(v=>v==="x"||v==="ok"||v===true||v==="✓"))r.tasks.forbidden=true;const map=[["cardio","cardioMinutes",30],["abs","absMinutes",20],["strength","strengthMinutes",30],["stretch","yogaMinutes",10],["hips","hipReps",150],["sleep","sleepHours",6],["cardio","steps",8000]];map.forEach(([task,key,min])=>{if(a[key]!=null&&a[key]!=="")r.tasks[task]=Number(a[key])>=min});records[d]=r;changed=true});if(changed)localStorage.setItem(KEY,JSON.stringify(records));}

function taskIds(){return groups.flatMap(g=>g.tasks.map(t=>t[0]))}
function isPlanned(date,id){return true}
function calcDay(date){const r=getRecord(date);let planned=0,done=0;const by={};groups.forEach(g=>{let p=0,d=0;g.tasks.forEach(([id])=>{if(isPlanned(date,id)){p++;planned++;if(r.tasks[id]){d++;done++}}});by[g.id]={planned:p,done:d,rate:p?Math.round(d/p*100):0}});return {planned,done,rate:planned?Math.round(done/planned*100):0,by}}
function saveCurrent(){const r=getRecord(currentDate);r.groupNotes=r.groupNotes||{};groups.forEach(g=>{const n=$("note_"+g.id);if(n)r.groupNotes[g.id]=n.value});r.reflection={win:$("reflectionWin").value,blocker:$("reflectionBlocker").value,tomorrow:$("tomorrowAction").value};r.metrics.weight=num("m_weight");r.forbiddenChecks={};settings.forbidden.forEach((_,i)=>{r.forbiddenChecks[i]=!!$("forbid_"+i)?.checked});records[currentDate]=r;localStorage.setItem(KEY,JSON.stringify(records));if(window.lifeosSaveHealthLog&&!window.lifeosSaveHealthLog(true))return;renderStats();renderDailyReport();toast("오늘 기록과 식단을 한 번에 저장했어.");}
